content.query:
let clubId = tostring("{ClubId}");
let partnerId = tostring("{PartnerId}");
union isfuzzy=true customEvents, traces, pageViews, requests
| where timestamp {TimeRange}
| extend Club = coalesce(tostring(customDimensions.ClubId), tostring(customDimensions.VacationClubID), tostring(customDimensions.VacationClubId), tostring(customDimensions.club_id))
| extend Partner = coalesce(tostring(customDimensions.PartnerId), tostring(customDimensions.partnerId), tostring(customDimensions.partner_id))
| where Club == clubId or (isnotempty(partnerId) and Partner == partnerId)
| summarize Events = count() by bin(timestamp, 1h)
| order by timestamp asc
| render timechart

let clubId = tostring("{ClubId}");
let partnerId = tostring("{PartnerId}");
union isfuzzy=true customEvents, traces, pageViews, requests
| where timestamp {TimeRange}
| extend Club = coalesce(tostring(customDimensions.ClubId), tostring(customDimensions.VacationClubID), tostring(customDimensions.VacationClubId), tostring(customDimensions.club_id))
| extend Partner = coalesce(tostring(customDimensions.PartnerId), tostring(customDimensions.partnerId), tostring(customDimensions.partner_id))
| where Club == clubId or (isnotempty(partnerId) and Partner == partnerId)
| project timestamp, itemType, name, message, operation_Name, Club, Partner, customDimensions
| order by timestamp desc
| take 100
